diff --git a/src/combinedoutputs.cpp b/src/combinedoutputs.cpp
new file mode 100644
index 00000000..5863ad36
--- /dev/null
+++ b/src/combinedoutputs.cpp
@@ -0,0 +1,156 @@
+// SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#include "combinedoutputs.h"
+
+#include <QRegularExpression>
+
+#include <KConfigGroup>
+
+#include <PulseAudioQt/Context>
+#include <PulseAudioQt/Module>
+#include <PulseAudioQt/Sink>
+
+using namespace std::chrono_literals;
+using namespace Qt::StringLiterals;
+
+namespace
+{
+constexpr auto MODULE_NAME = "module-combine-sink"_L1;
+constexpr auto NAME_PREFIX = "plasma_combined_"_L1;
+
+PulseAudioQt::Module *moduleFor(const QString &name)
+{
+    const auto modules = PulseAudioQt::Context::instance()->modules();
+    for (auto module : modules) {
+        if (module->name() == MODULE_NAME && module->argument().startsWith(u"sink_name=%1 "_s.arg(name))) {
+            return module;
+        }
+    }
+    return nullptr;
+}
+
+QStringList moduleDevices(PulseAudioQt::Module *module)
+{
+    static const QRegularExpression slavesExpression(u"slaves=(\\S+)"_s);
+    return slavesExpression.match(module->argument()).captured(1).split(u',', Qt::SkipEmptyParts);
+}
+
+void loadModule(const QString &name, const QStringList &devices, QString description)
+{
+    description.remove(QRegularExpression(u"[\"'\\\\]"_s));
+    PulseAudioQt::Context::instance()->loadModule(
+        MODULE_NAME,
+        u"sink_name=%1 slaves=%2 sink_properties='device.description=\"%3\"'"_s.arg(name, devices.join(u','), description));
+}
+} // namespace
+
+CombinedOutputs::CombinedOutputs(QObject *parent)
+    : QObject(parent)
+    , m_config(KSharedConfig::openConfig(u"plasmaparc"_s))
+    , m_configWatcher(KConfigWatcher::create(m_config))
+{
+    connect(m_configWatcher.get(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.parent().name() == "CombinedOutputs"_L1) {
+            Q_EMIT namesChanged();
+        }
+    });
+
+    m_restoreTimer.setInterval(1s);
+    m_restoreTimer.setSingleShot(true);
+    connect(&m_restoreTimer, &QTimer::timeout, this, &CombinedOutputs::restore);
+}
+
+QStringList CombinedOutputs::names() const
+{
+    return m_config->group(u"CombinedOutputs"_s).groupList();
+}
+
+void CombinedOutputs::create(const QStringList &sinkNames)
+{
+    QStringList descriptions;
+    const auto sinks = PulseAudioQt::Context::instance()->sinks();
+    for (const QString &sinkName : sinkNames) {
+        auto it = std::find_if(sinks.cbegin(), sinks.cend(), [&sinkName](PulseAudioQt::Sink *sink) {
+            return sink->name() == sinkName;
+        });
+        descriptions << (it != sinks.cend() && !(*it)->description().isEmpty() ? (*it)->description() : sinkName);
+    }
+
+    KConfigGroup outputs = m_config->group(u"CombinedOutputs"_s);
+    int number = 1;
+    while (outputs.hasGroup(NAME_PREFIX + QString::number(number)) || moduleFor(NAME_PREFIX + QString::number(number))) {
+        ++number;
+    }
+    const QString name = NAME_PREFIX + QString::number(number);
+    const QString description = descriptions.join(u" + "_s);
+
+    KConfigGroup output = outputs.group(name);
+    output.writeEntry("Description", description, KConfig::Notify);
+    output.writeEntry("Devices", sinkNames, KConfig::Notify);
+    m_config->sync();
+
+    loadModule(name, sinkNames, description);
+    Q_EMIT namesChanged();
+}
+
+void CombinedOutputs::remove(const QString &name)
+{
+    m_config->group(u"CombinedOutputs"_s).group(name).deleteGroup(KConfig::Notify);
+    m_config->sync();
+
+    if (auto module = moduleFor(name)) {
+        PulseAudioQt::Context::instance()->unloadModule(module);
+    }
+    Q_EMIT namesChanged();
+}
+
+void CombinedOutputs::restoreAutomatically()
+{
+    auto context = PulseAudioQt::Context::instance();
+    connect(context, &PulseAudioQt::Context::stateChanged, &m_restoreTimer, qOverload<>(&QTimer::start));
+    connect(context, &PulseAudioQt::Context::sinkAdded, &m_restoreTimer, qOverload<>(&QTimer::start));
+    m_restoreTimer.start();
+}
+
+void CombinedOutputs::restore()
+{
+    auto context = PulseAudioQt::Context::instance();
+    if (context->state() != PulseAudioQt::Context::State::Ready) {
+        return;
+    }
+
+    QStringList sinkNames;
+    const auto sinks = context->sinks();
+    for (auto sink : sinks) {
+        sinkNames << sink->name();
+    }
+
+    m_config->reparseConfiguration();
+    const KConfigGroup outputs = m_config->group(u"CombinedOutputs"_s);
+    const auto names = outputs.groupList();
+    for (const QString &name : names) {
+        const KConfigGroup output = outputs.group(name);
+        QStringList devices = output.readEntry("Devices", QStringList());
+        // The audio server refuses to combine devices that don't exist (yet), e.g. disconnected headphones
+        devices.removeIf([&sinkNames](const QString &device) {
+            return !sinkNames.contains(device);
+        });
+        if (devices.isEmpty()) {
+            continue;
+        }
+
+        if (auto module = moduleFor(name)) {
+            const QStringList loadedDevices = moduleDevices(module);
+            if (std::all_of(devices.cbegin(), devices.cend(), [&loadedDevices](const QString &device) {
+                    return loadedDevices.contains(device);
+                })) {
+                continue;
+            }
+            context->unloadModule(module);
+        }
+        loadModule(name, devices, output.readEntry("Description", name));
+    }
+}
+
+#include "moc_combinedoutputs.cpp"
