+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#pragma once
+
+#include <QObject>
+#include <QTimer>
+#include <qqmlregistration.h>
+
+#include <KConfigWatcher>
+#include <KSharedConfig>
+
+// Virtual output devices that play everything sent to them on several chosen output devices at once.
+class CombinedOutputs : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    Q_PROPERTY(QStringList names READ names NOTIFY namesChanged)
+public:
+    explicit CombinedOutputs(QObject *parent = nullptr);
+
+    [[nodiscard]] QStringList names() const;
+
+    Q_INVOKABLE void create(const QStringList &sinkNames);
+    Q_INVOKABLE void remove(const QString &name);
+
+    // Loads the saved combined outputs and reloads them when one of their devices appears
+    void restoreAutomatically();
+
+Q_SIGNALS:
+    void namesChanged();
+
+private:
+    void restore();
+
+    KSharedConfig::Ptr m_config;
+    KConfigWatcher::Ptr m_configWatcher;
+    QTimer m_restoreTimer;
+};
